class Solution {
    public String removeOccurrences(String s,String part){
        StringBuilder builder=new StringBuilder();
        for(char value:s.toCharArray()){
            builder.append(value);
            if(builder.length()>=part.length()){
                boolean match=true;
                int start=builder.length()-part.length();
                for(int i=0;i<part.length();i++)if(builder.charAt(start+i)!=part.charAt(i)){
                    match=false;
                    break;
                }
                if(match)builder.delete(start,builder.length());
            }
        }
        return builder.toString();
    }
}

code.kotlin:
class Solution {
    fun removeOccurrences(s:String,part:String):String{
        val builder=StringBuilder();
        for(value in s){
            builder.append(value);
            if(builder.length>=part.length){
                val start=builder.length-part.length;
                var match=true;
                for(i in part.indices)if(builder[start+i]!=part[i]){
                    match=false;
                    break
                };
                if(match)builder.delete(start,builder.length)
            }
        };
        return builder.toString()
    }
}

